find ~ \( -name node_modules -o -name .git -o -name AppData -o -name Library \) -prune -o -type d ! -name ".env*" -print -o -type f -name ".env*" -print 2>/dev/null | awk '/\/\.env[^\/]*$/{n++; printf "\r%-60s\n",$0; fflush(); next} {d++; if(d%100==0){printf "\rSearched %d folders, found %d...",d,n; fflush()}} END{printf "\r%-60s\n",sprintf("Searched %d folders, found %d .env files",d,n)}'
